"""Seam coverage for upstream #1025: the Apex (UILess) repeated-composition bug.

A UILess host flattens the UI, so the C++ client paints one reply's
``commitString`` as the composition (PIMEClient.cpp ``updateCommitString``)
and the plain ``compositionString`` right after it (``updateComposition``).
The interleaved repeat the reporter saw comes from a reply that carries the
same text in both layers; the two reply shapes are therefore pinned here:

* while a syllable is in progress the reply carries only ``compositionString``;
* the flush reply (Enter) carries the text once — non-empty ``commitString``
  with an empty ``compositionString`` — so the flattened host commits once;
* a forced termination (``onCompositionTerminated`` with ``forced: true``)
  clears both buffers so no stale layer replays into the next key's reply.

Each case drives the real chewing service (the bundled libchewing) through
``handleRequest``, the same seam the C++ client uses for a UiLess session
(``isUiLess`` enters at PIMEClient.cpp:705; the Python side of the same
decision is ``onCompositionTerminated`` in chewing_ime.py).
"""

import os
import sys
import unittest

ROOT = os.path.abspath(os.path.join(os.path.dirname(__file__), os.path.pardir))
for _path in (os.path.join(ROOT, "python"), os.path.dirname(os.path.abspath(__file__))):
    if _path not in sys.path:
        sys.path.insert(0, _path)

import ime_smoke_runner  # noqa: E402 - located after ROOT is known
ime_smoke_runner.install_windows_shims()

VK_RETURN = 0x0D

# Hsu-layout key sequences, as the bundled libchewing answers them.
# 新(sy1) 酷(ku4) 音(in1) 會(hui4): the reporter's four steps.
SY1_KEYS = ("v", "u", "p", " ")
KU4_KEYS = ("d", "k", "4")
IN1_KEYS = ("u", "p", " ")
HUI4_KEYS = ("c", "j", "o", "4")
REPORTER_SEQUENCE = SY1_KEYS + KU4_KEYS + IN1_KEYS + HUI4_KEYS
# The first-candidate strings libchewing commits for that sequence. The
# bundled build answers 心 for ㄒㄧㄣ, the CI runner's system library 新; both
# are measured, and the shape of the reply is the contract.
OBSERVED_FLUSH_TEXTS = ("心客因會", "新客因會")


class UiLessFakeClient:
    """The init-request flags PIMEClient.cpp sends for an Apex-like host."""

    isWindows8Above = True
    isMetroApp = False
    isUiLess = True
    isConsole = False


class UiLessCompositionTests(unittest.TestCase):
    """Drives the real chewing service through the client's reply seam."""

    def setUp(self):
        from input_methods.chewing import chewing_ime

        self.client = UiLessFakeClient()
        self.service = chewing_ime.ChewingTextService(self.client)
        self.service.handleRequest(
            {"method": "onActivate", "isKeyboardOpen": True, "seqNum": 1})

    def layers(self, reply):
        return {k: reply[k] for k in ("commitString", "compositionString") if k in reply}

    def key(self, ch, key_code=None):
        code = ord(ch) if key_code is None else key_code
        return self.service.handleRequest({
            "method": "onKeyDown", "charCode": code, "keyCode": code,
            "repeatCount": 1, "scanCode": 0, "isExtended": False,
            "keyStates": [0] * 256, "seqNum": 2})

    def test_session_is_uiless(self):
        self.assertTrue(self.client.isUiLess, "the host flattens the UI")
        self.assertFalse(self.client.isMetroApp)
        self.assertFalse(self.client.isConsole)

    def test_in_progress_reply_carries_only_the_composition_layer(self):
        # While a syllable is incomplete the host must see exactly one text
        # layer: the preedit, with no commitString riding along.
        expected = ["ㄒ", "ㄒㄧ", "ㄒㄧㄣ"]
        for ch, wanted in zip(("v", "u", "p"), expected):
            reply = self.key(ch)
            self.assertNotIn("commitString", reply,
                             f"{ch}: no commit layer while composing")
            self.assertEqual(self.layers(reply), {"compositionString": wanted})
        self.assertTrue(self.service.isComposing())

    def test_tone_key_collapses_syllable_into_the_single_buffer(self):
        for ch in SY1_KEYS:
            reply = self.key(ch)
        layers = self.layers(reply)
        # The two libchewing builds this suite meets answer the first candidate
        # of ㄒㄧㄣ differently — the bundled 心, the runner's system 新 — so the
        # glyph is matched against the measured set and the shape carries the
        # contract: one layer, no commit riding along.
        self.assertEqual(set(layers), {"compositionString"},
                         "the tone key moves the syllable into the buffer, still one layer")
        self.assertIn(layers["compositionString"], {"心", "新"})

    def test_flush_reply_commits_once_with_one_non_empty_layer(self):
        for ch in REPORTER_SEQUENCE:
            self.key(ch)
        last_composition = self.service.compositionString

        reply = self.key("\r", VK_RETURN)
        layers = self.layers(reply)

        # The single-commit outcome: exactly one of the two layers is non-empty,
        # so the flattened UiLess host paints the text once, not interleaved.
        non_empty = [v for v in layers.values() if v]
        self.assertEqual(len(non_empty), 1,
                         f"flush reply must carry one text layer, got {layers}")
        self.assertIn(layers.get("commitString"), OBSERVED_FLUSH_TEXTS,
                      "the committed text is the first-candidate chain of the "
                      "sequence, whichever libchewing build answers it")
        self.assertEqual(layers.get("compositionString"), "")
        self.assertEqual(layers.get("commitString"), last_composition,
                         "the flush commits what the buffer showed, once")
        self.assertTrue(reply["return"], "the host must not also see the Enter key")

    def test_forced_termination_clears_both_layers(self):
        for ch in ("v", "u"):
            self.key(ch)
        self.assertTrue(self.service.isComposing())

        reply = self.service.handleRequest(
            {"method": "onCompositionTerminated", "forced": True, "seqNum": 3})

        self.assertTrue(reply["success"])
        for name, value in self.layers(reply).items():
            self.assertEqual(value, "", f"{name} must be cleared by a forced close")
        self.assertEqual(self.service.commitString, "")
        self.assertEqual(self.service.compositionString, "")
        self.assertFalse(self.service.isComposing())

    def test_next_reply_after_forced_termination_starts_fresh(self):
        for ch in ("v", "u"):
            self.key(ch)
        self.service.handleRequest(
            {"method": "onCompositionTerminated", "forced": True, "seqNum": 3})

        reply = self.key("p")

        # No interleaved repeat: the stale ㄒㄧ buffer must not replay; the
        # new reply shows only the one key typed after the close.
        self.assertEqual(self.layers(reply), {"compositionString": "ㄣ"})


if __name__ == "__main__":
    unittest.main()
